mapper.select:
SELECT r.*, p.project_name, p.leader AS leader, (p.budget - COALESCE(p.used_amount, 0)) AS remaining_budget, (SELECT u.nick_name FROM sys_user u WHERE u.user_id = r.create_by) AS applicant_name, (SELECT rb.reimbursement_code FROM pms_reimbursement rb WHERE rb.request_id = r.id AND rb.del_flag = '0' ORDER BY rb.id DESC LIMIT 1) AS reimbursement_code FROM pms_procurement_request r LEFT JOIN pms_project p ON r.project_id = p.id AND p.del_flag = '0'
AND r.del_flag = '0'
AND r.request_code LIKE CONCAT('%', #{bo.requestCode}, '%')
AND r.title LIKE CONCAT('%', #{bo.title}, '%')
AND r.project_id = #{bo.projectId}
AND r.status = #{bo.status}
AND r.purchase_type = #{bo.purchaseType}
AND r.title_type = #{bo.titleType}
AND r.fund_status = #{bo.fundStatus}
AND EXISTS (SELECT 1 FROM sys_user su WHERE su.user_id = r.create_by AND su.nick_name LIKE CONCAT('%', #{bo.applicantName}, '%'))
AND r.create_time BETWEEN #{bo.params.beginCreateTime} AND #{bo.params.endCreateTime}
ORDER BY r.create_time DESC
